// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address candidate) public {
        // The test contract itself is the deployer, hence the admin.
        // Rule: the admin can always set the owner to any candidate address,
        // and afterwards c.owner() equals that candidate.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(candidate) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == candidate);
    }
}
